def protocol_handlers(protocol_version=None):
    supported_protocols = {
        (3, 5): ProtocolHandlerV3_5,
        (3, 4): ProtocolHandlerV3_4,
        (3, 3): ProtocolHandlerV3_3,
        (3, 2): ProtocolHandlerV3_2,
        (3, 1): ProtocolHandlerV3_1,
        (3, 0): ProtocolHandlerV3_0,
        (2, 3): ProtocolHandlerV2_3,
        (2, 2): ProtocolHandlerV2_2,
        (2, 1): ProtocolHandlerV2_1,
        (2, 0): ProtocolHandlerV2_0,
    }
    if protocol_version is None:
        # If no protocol version is specified, return all available versions
        return supported_protocols
    if type(protocol_version) is not tuple:
        raise TypeError("Protocol version must be specified as a tuple")
    if protocol_version not in supported_protocols:
