def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    """
    if first_level:
        # If the dictionary represents the whole observer schema,
        # copy the values of the identifying fields from the manifest file.
        identifying_fields = ["kind", "apiVersion"]
        generated_dict = {
            field: manifest_dict.get(field) for field in identifying_fields
        }

    else:
        # Otherwise, create a new dictionary from the manifest dict
        # and replace all non-list and non-dict values by ``None``.
        generated_dict = {
            key: None if not isinstance(val, (list, dict)) else generate_default_observer_schema_dict(val)
            for key, val in manifest_dict.items()
        }

    return generated_dict

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for i in range(len(observer_schema)):
        field = observer_schema[i]
        value = response[i] if i < len(response) else None
        if field not in last_applied_manifest:
            last_applied_manifest[field] = value
        elif isinstance(last_applied_manifest[field], list) and isinstance(value, list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[field], value, observer_schema[field])
        else:
            last_applied_manifest[field] = value

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, value in observer_schema.items():
        if field not in response:
            raise KeyError(f"Observed field '{field}' not present in Kubernetes response")
        if isinstance(value, dict):
            last_applied_manifest[field] = update_last_applied_manifest_dict_from_resp(last_applied_manifest.get(field, {}), value, response[field])
        else:
            last_applied_manifest[field] = response[field]
    return last_applied_manifest

