def validate_fixity(self, fixity, manifest_files):
    fixity_dict = fixity.to_dict()
    for file_path, fixity_info in fixity_dict.items():
        if file_path not in manifest_files:
            raise ValueError(f"Fixity information for file '{file_path}' not found in manifest")
        if not isinstance(fixity_info, dict):
            raise ValueError(f"Invalid fixity information for file '{file_path}': not a dictionary")
        if not fixity_info.get('hashes'):
            raise ValueError(f"Missing hashes in fixity information for file '{file_path}'")
        for algorithm, hash_value in fixity_info['hashes'].items():
            if not isinstance(hash_value, str):
                raise ValueError(f"Invalid hash value for algorithm '{algorithm}' in fixity information for file '{file_path}'")
            try:
                hash_value.decode('utf-8')
            except UnicodeDecodeError:
                raise ValueError(f"Invalid encoding for hash value for algorithm '{algorithm}' in fixity information for file '{file_path}'")
        for fixity_field in fixity_info.get('extra_fields', []):
            if fixity_field not in self.fixity_fields:
                raise ValueError(f"Invalid fixity field '{fixity_field}' in fixity information for file '{file_path}'")
    return True

