def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    for node in self.storage_root.values():
        if node.type != 'dir':
            continue
        for key, value in node.items():
            if not validate_objects and key == 'objects':
                continue
            if value.type == 'file':
                num_objects += 1
                if check_digests and value.calculate_digest() != value.digest:
