def paging(response, max_results):
    # generator function to yield each page of results 
    def chunk_response(response, max_results):
        # divide the response into chunks of max_results
        for i in range(0, len(response), max_results):
            yield response[i:i+max_results]
    # start the generator
    page = 1
    chunk_size = max_results
    while True:
        try:
            yield chunk_response(response, max_results)
            page += 1
        except IndexError:
            break

