def popitem(self):
    # Check if the cache is empty
    if len(self.cache) == 0:
        return None

    # Find the key of the least recently used item
    lru_key = None
    for key, node in self.cache.items():
        if lru_key is None or node.last_accessed < self.cache[lru_key].last_accessed:
            lru_key = key

    # Remove and return the least recently used item
    value = self.cache[lru_key]
    del self.cache[lru_key]
    return (lru_key, value)

def popitem(self):
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    most_recent_key = None
    for key, _ in self.items():
        if most_recent_key is None or self._access_order.index(key) > self._access_order.index(most_recent_key):
            most_recent_key = key
    value = self.pop(most_recent_key)
    return most_recent_key, value

