def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Check if the request has a matrix parameter
    if "matrix" in request.parameter:
        # Check if the matrix parameter is a valid matrix
        try:
            matrix = np.array(request.parameter["matrix"]).astype(np.float32)
            if matrix.shape != (4, 4):
                return False
            if not np.all(np.isfinite(matrix)):
                return False
        except Exception:
            return False
        return True
    return False

def find_tags(text, replacer=None):
    """
    Find tags in text and return a set of tags and the original or replaced text.
    """
    tags = set()
    for word in text.split():
        if word.startswith("#"):
            tags.add(word[1:])
            if replacer is not None:
                text = text.replace(word, replacer(word[1:]))
    return tags, text

