def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try to parse the document as JSON
    try:
        json_data = json.loads(document)
        # If the document is in JSON format, it should have a 'links' key
        if 'links' in json_data:
            # Extract the 'links' key and convert it to a dictionary
            links = json_data['links']
            link_dict = {}
            for link in links:
                link_dict[link['rel']] = link['href']
            return link_dict
        else:
            # If the document is not in JSON format, it should be in XRD format
            xrd_root = ET.fromstring(document)
            xrd_links = xrd_root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link')
            link_dict = {}
            for xrd_link in xrd_links:
                link_dict[xrd_link.attrib['rel']] = xrd_link.attrib['href']
            return link_dict
    except Exception as e:
        print("Error parsing Diaspora webfinger:", e)
        return {}

