def validate_from_content(spec_content=None):
    if not spec_content:
        raise IRValidatorException("No spec content provided")
    data = yaml.safe_load(spec_content)
    if not data:
        raise IRValidatorException("Spec content is empty")
    required_fields = {"models", "facts", "relationships"}
    missing_fields = required_fields - data.keys()
    if missing_fields:
        raise IRValidatorException(f"Missing mandatory fields: {missing_fields}")
    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Args:
        parser_dict (dict): The dictionary containing the parsed spec file.

    Returns:
        dict: The updated dictionary with the included groups.
    """
    include_dict = parser_dict.get("include")
    if not include_dict:
        return parser_dict

    for include_key, include_value in include_dict.items():
        if isinstance(include_value, list):
            for i in range(len(include_value)):
                if isinstance(include_value[i], dict):
                    include_value[i] = _include_groups(self, include_value[i])
        elif isinstance(include_value, dict):
            include_value = _include_groups(self, include_value)
        else:
            raise ValueError("Invalid include value in spec file.")

    return parser_dict

def get_spec_defaults(self, spec):
    """
    Resolve arguments' values from spec and other sources.
    """
    resolved_args = {}
    for arg_name, arg_value in spec.items():
